import * as BABYLON from 'babylonjs';

/**
 * Background sci-fi city — the imported building placed as a skyline.
 *
 * Collisions are generated by casting DOWNWARD RAYS against the actual mesh
 * triangles at a dense grid over the footprint, so each collider's top is the
 * EXACT visible surface height at that spot — including terraces and the small
 * air ducts on the roof. No bbox approximation, no floating/sinking feet.
 */

type Box = { x: number; y: number; z: number; w: number; h: number; d: number };

/** Möller–Trumbore ray/triangle intersection. Returns hit Y or null. */
function rayTriY(
  ox: number, oy: number, oz: number,       // ray origin
  ax: number, ay: number, az: number,       // triangle A
  bx: number, by: number, bz: number,       // triangle B
  cx: number, cy: number, cz: number,       // triangle C
): number | null {
  // Ray direction dir = (0,-1,0). Standard Möller–Trumbore.
  const e1x = bx - ax, e1y = by - ay, e1z = bz - az;
  const e2x = cx - ax, e2y = cy - ay, e2z = cz - az;
  // p = dir × e2 = (-e2z, 0, e2x)
  const px = -e2z, py = 0, pz = e2x;
  const det = e1x * px + e1y * py + e1z * pz;
  if (Math.abs(det) < 1e-9) return null;
  const invDet = 1 / det;
  const tx = ox - ax, ty = oy - ay, tz = oz - az;
  const u = (tx * px + ty * py + tz * pz) * invDet;
  if (u < -1e-6 || u > 1 + 1e-6) return null;
  // q = tvec × e1
  const qx = ty * e1z - tz * e1y;
  const qy = tz * e1x - tx * e1z;
  const qz = tx * e1y - ty * e1x;
  const v = -qy * invDet; // dir·q = -qy
  if (v < -1e-6 || u + v > 1 + 1e-6) return null;
  const t = (e2x * qx + e2y * qy + e2z * qz) * invDet;
  if (t < 0) return null;
  return oy - t; // hit y = oy + t*dir.y = oy - t
}

export class SciFiCity {
  private scene: BABYLON.Scene;
  private sources: BABYLON.Mesh[] = [];
  private root: BABYLON.TransformNode;

  constructor(scene: BABYLON.Scene) {
    this.scene = scene;
    this.root = new BABYLON.TransformNode('sciFiCity', scene);
  }

  public async load(onCollider: (c: Box) => void) {
    const res = await BABYLON.SceneLoader.ImportMeshAsync('', '/models/sci_fi_city/', 'sci_fi_building_01.glb', this.scene);
    const meshes = res.meshes.filter((m) => m instanceof BABYLON.Mesh && m.getTotalVertices() > 0) as BABYLON.Mesh[];
    if (!meshes.length) return;

    // Bake all sub-meshes into ONE local vertex/index soup (base at y=0, centred on XZ).
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, minZ = Infinity, maxZ = -Infinity;
    const raw: { pos: Float32Array | ArrayLike<number>; idx: ArrayLike<number>; wm: BABYLON.Matrix }[] = [];
    for (const m of meshes) {
      m.computeWorldMatrix(true);
      const bb = m.getBoundingInfo().boundingBox;
      minX = Math.min(minX, bb.minimumWorld.x); maxX = Math.max(maxX, bb.maximumWorld.x);
      minY = Math.min(minY, bb.minimumWorld.y); maxY = Math.max(maxY, bb.maximumWorld.y);
      minZ = Math.min(minZ, bb.minimumWorld.z); maxZ = Math.max(maxZ, bb.maximumWorld.z);
      raw.push({ pos: m.getVerticesData(BABYLON.VertexBuffer.PositionKind)!, idx: m.getIndices()!, wm: m.getWorldMatrix().clone() });
    }
    const cx = (minX + maxX) / 2, cz = (minZ + maxZ) / 2;
    const W = maxX - minX, D = maxZ - minZ, H = maxY - minY;

    const verts: number[] = []; // x,y,z triplets, local space
    const tris: number[] = [];  // indices into verts
    const v = new BABYLON.Vector3();
    for (const r of raw) {
      const base = verts.length / 3;
      for (let i = 0; i < r.pos.length; i += 3) {
        BABYLON.Vector3.TransformCoordinatesToRef(new BABYLON.Vector3(r.pos[i], r.pos[i + 1], r.pos[i + 2]), r.wm, v);
        verts.push(v.x - cx, v.y - minY, v.z - cz);
      }
      for (let i = 0; i < r.idx.length; i++) tris.push(base + r.idx[i]);
    }

    /** Exact surface height at local XZ via downward ray against real triangles. */
    function surfaceAtLocal(x: number, z: number): number | null {
      let top: number | null = null;
      const oy = H + 2;
      for (let i = 0; i < tris.length; i += 3) {
        const a = tris[i] * 3, b = tris[i + 1] * 3, c = tris[i + 2] * 3;
        const y = rayTriY(x, oy, z,
          verts[a], verts[a + 1], verts[a + 2],
          verts[b], verts[b + 1], verts[b + 2],
          verts[c], verts[c + 1], verts[c + 2]);
        if (y !== null && (top === null || y > top)) top = y;
      }
      return top;
    }

    // Build the visible baked source meshes for instancing.
    for (const m of meshes) {
      const pos = m.getVerticesData(BABYLON.VertexBuffer.PositionKind)!;
      const uv = m.getVerticesData(BABYLON.VertexBuffer.UVKind);
      const nor = m.getVerticesData(BABYLON.VertexBuffer.NormalKind);
      const idx = m.getIndices()!;
      const wm = m.getWorldMatrix();
      const baked: number[] = [], uvs: number[] = [], norms: number[] = [];
      const nv = new BABYLON.Vector3();
      for (let i = 0; i < pos.length; i += 3) {
        BABYLON.Vector3.TransformCoordinatesToRef(new BABYLON.Vector3(pos[i], pos[i + 1], pos[i + 2]), wm, v);
        baked.push(v.x - cx, v.y - minY, v.z - cz);
        if (uv) uvs.push(uv[(i / 3) * 2], uv[(i / 3) * 2 + 1]);
        if (nor) { BABYLON.Vector3.TransformNormalToRef(new BABYLON.Vector3(nor[i], nor[i + 1], nor[i + 2]), wm, nv); norms.push(nv.x, nv.y, nv.z); }
      }
      if (!nor) { const n: number[] = []; BABYLON.VertexData.ComputeNormals(baked, idx, n); norms.push(...n); }
      const vd = new BABYLON.VertexData();
      vd.positions = baked; vd.indices = idx; vd.normals = norms;
      if (uv) vd.uvs = uvs;
      const bakedMesh = new BABYLON.Mesh('sciFiBuildingSrc', this.scene);
      vd.applyToMesh(bakedMesh);
      bakedMesh.material = m.material;
      bakedMesh.receiveShadows = true;
      bakedMesh.setEnabled(false);
      this.sources.push(bakedMesh);
    }

    // Dispose original imports (they sit at origin over the start travelator).
    for (const m of meshes) m.dispose(false, false);
    if (res.transformNodes) for (const n of res.transformNodes) n.dispose(false, false);

    // Just TWO sci-fi buildings in the whole level, pulled closer in Z so
    // they read in the background without crowding the play strip (z≈0).
    const spots: { x: number; z: number; s: number }[] = [
      { x: 70, z: 30, s: 1.5 },
      { x: 400, z: 36, s: 1.8 },
    ];

    // Dense exact heightfield per building: 10x10 cells, top from real ray hits.
    const N = 10;
    for (const s of spots) {
      const bRoot = new BABYLON.TransformNode(`sciFiBuilding${spots.indexOf(s)}`, this.scene);
      bRoot.parent = this.root;
      bRoot.position.set(s.x, 0, s.z);
      bRoot.scaling.setAll(s.s);
      for (const src of this.sources) {
        const inst = src.createInstance('sciFiBuilding_part');
        inst.parent = bRoot;
        inst.isPickable = false;
        inst.receiveShadows = true;
      }
      const cellW = (W * s.s) / N, cellD = (D * s.s) / N;
      for (let gx = 0; gx < N; gx++) {
        for (let gz = 0; gz < N; gz++) {
          const lx = -W / 2 + ((gx + 0.5) / N) * W;
          const lz = -D / 2 + ((gz + 0.5) / N) * D;
          const hit = surfaceAtLocal(lx, lz);
          if (hit === null || hit < 0.3) continue;
          const top = hit * s.s;
          onCollider({
            x: s.x - (W * s.s) / 2 + (gx + 0.5) * cellW,
            y: top / 2,
            z: s.z - (D * s.s) / 2 + (gz + 0.5) * cellD,
            w: cellW * 1.06, h: top, d: cellD * 1.06,
          });
        }
      }
    }
  }

  public dispose() {
    this.root.dispose(false, true);
    for (const s of this.sources) s.dispose();
  }
}
